  ccxt::any parseMarket(ccxt::any market) override {
    ccxt::any type = this->safeString(market, std::string("instrument_type"));
    ccxt::any marketType = ccxt::any{};
    ccxt::any spot = false;
    ccxt::any margin = true;
    ccxt::any swap = false;
    ccxt::any option = false;
    ccxt::any linear = ccxt::any{};
    ccxt::any inverse = ccxt::any{};
    ccxt::any baseId = this->safeString(market, std::string("base_currency"));
    ccxt::any quoteId = this->safeString(market, std::string("quote_currency"));
    ccxt::any base = this->safeCurrencyCode(baseId);
    ccxt::any quote = this->safeCurrencyCode(quoteId);
    ccxt::any marketId =
        this->safeString(market, std::string("instrument_name"));
    ccxt::any symbol = add(add(base, std::string("/")), quote);
    ccxt::any settleId = ccxt::any{};
    ccxt::any settle = ccxt::any{};
    ccxt::any expiry = ccxt::any{};
    ccxt::any strike = ccxt::any{};
    ccxt::any optionType = ccxt::any{};
    ccxt::any optionLetter = ccxt::any{};
    if (isTrue(isEqual(type, std::string("erc20")))) {
      spot = true;
      marketType = std::string("spot");
    } else if (isTrue(isEqual(type, std::string("perp")))) {
      margin = false;
      settleId = std::string("USDC");
      settle = this->safeCurrencyCode(settleId);
      symbol =
          add(add(add(add(base, std::string("/")), quote), std::string(":")),
              settle);
      swap = true;
      linear = true;
      inverse = false;
      marketType = std::string("swap");
    } else if (isTrue(isEqual(type, std::string("option")))) {
      settleId = std::string("USDC");
      settle = this->safeCurrencyCode(settleId);
      margin = false;
      option = true;
      marketType = std::string("option");
      ccxt::any optionDetails =
          this->safeDict(market, std::string("option_details"));
      expiry = this->safeTimestamp(optionDetails, std::string("expiry"));
      strike = this->safeInteger(optionDetails, std::string("strike"));
      optionLetter =
          this->safeString(optionDetails, std::string("option_type"));
      symbol = add(
          add(add(add(add(add(add(add(add(add(base, std::string("/")), quote),
                                      std::string(":")),
                                  settle),
                              std::string("-")),
                          this->yymmdd(expiry)),
                      std::string("-")),
                  this->numberToString(strike)),
              std::string("-")),
          optionLetter);
      if (isTrue(isEqual(optionLetter, std::string("P")))) {
        optionType = std::string("put");
      } else {
        optionType = std::string("call");
      }
      linear = true;
      inverse = false;
    }
    ccxt::any contractSize =
        (isTrue((spot)) ? ccxt::any(ccxt::any{}) : ccxt::any(1));
    ccxt::any isContract = (isTrue(swap) || isTrue(option));
    return this->safeMarketStructure(ccxt::dict{
        {std::string("id"), marketId},
        {std::string("symbol"), symbol},
        {std::string("base"), base},
        {std::string("quote"), quote},
        {std::string("settle"), settle},
        {std::string("baseId"), baseId},
        {std::string("quoteId"), quoteId},
        {std::string("settleId"), settleId},
        {std::string("type"), marketType},
        {std::string("spot"), spot},
        {std::string("margin"), margin},
        {std::string("swap"), swap},
        {std::string("future"), false},
        {std::string("option"), option},
        {std::string("active"),
         this->safeBool(market, std::string("is_active"))},
        {std::string("contract"), isContract},
        {std::string("linear"), linear},
        {std::string("inverse"), inverse},
        {std::string("contractSize"), contractSize},
        {std::string("expiry"), expiry},
        {std::string("expiryDatetime"), this->iso8601(expiry)},
        {std::string("taker"),
         this->safeNumber(market, std::string("taker_fee_rate"))},
        {std::string("maker"),
         this->safeNumber(market, std::string("maker_fee_rate"))},
        {std::string("strike"), strike},
        {std::string("optionType"), optionType},
        {std::string("precision"),
         ccxt::dict{
             {std::string("amount"),
              this->safeNumber(market, std::string("amount_step"))},
             {std::string("price"),
              this->safeNumber(market, std::string("tick_size"))},
         }},
        {std::string("limits"),
         ccxt::dict{
             {std::string("leverage"),
              ccxt::dict{
                  {std::string("min"), ccxt::any{}},
                  {std::string("max"), ccxt::any{}},
              }},
             {std::string("amount"),
              ccxt::dict{
                  {std::string("min"),
                   this->safeNumber(market, std::string("minimum_amount"))},
                  {std::string("max"),
                   this->safeNumber(market, std::string("maximum_amount"))},
              }},
             {std::string("price"),
              ccxt::dict{
                  {std::string("min"), ccxt::any{}},
                  {std::string("max"), ccxt::any{}},
              }},
             {std::string("cost"),
              ccxt::dict{
                  {std::string("min"), ccxt::any{}},
                  {std::string("max"), ccxt::any{}},
              }},
         }},
        {std::string("created"), ccxt::any{}},
        {std::string("info"), market},
    });
  }

