                 ccxt::any result =
                     this->safeDict(response, std::string("result"));
                 ccxt::any rawOrder =
                     this->safeDict(result, std::string("order"), ccxt::dict{});
                 ccxt::any order = this->parseOrder(rawOrder, market);
                 return order;
