  /**
   * @method
   * @name derive#cancelOrder
   * @see https://docs.derive.xyz/reference/post_private-cancel
   * @description cancels an open order
   * @param {string} id order id
   * @param {string} symbol unified symbol of the market the order was made in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.trigger] whether the order is a trigger/algo order
   * @param {string} [params.subaccount_id] *required* the subaccount id
   * @returns {object} An [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  cancelOrder(ccxt::any id, ccxt::any symbol = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(symbol, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " cancelOrder() requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any isTrigger =
                     this->safeBool2(params, std::string("trigger"),
                                     std::string("stop"), false);
                 ccxt::any subaccountId = ccxt::any{};
                 ccxt::any subaccountIdparamsVariable =
                     this->handleDeriveSubaccountId(std::string("cancelOrder"),
                                                    params);
                 subaccountId = ::getValue(subaccountIdparamsVariable, 0);
                 params = ::getValue(subaccountIdparamsVariable, 1);
                 params = this->omit(params, ccxt::list{std::string("trigger"),
                                                        std::string("stop")});
                 ccxt::any request = ccxt::dict{
                     {std::string("instrument_name"),
                      ::getValue(market, std::string("id"))},
                     {std::string("subaccount_id"), subaccountId},
                 };
                 ccxt::any clientOrderIdUnified =
                     this->safeString(params, std::string("clientOrderId"));
                 ccxt::any clientOrderIdExchangeSpecific = this->safeString(
                     params, std::string("label"), clientOrderIdUnified);
                 ccxt::any isByClientOrder =
                     !isEqual(clientOrderIdExchangeSpecific, ccxt::any{});
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isByClientOrder)) {
                   ::setValue(request, std::string("label"),
                              clientOrderIdExchangeSpecific);
                   params = this->omit(params,
                                       ccxt::list{std::string("clientOrderId"),
                                                  std::string("label")});
                   response = awaitValue(this->privatePostCancelByLabel(
                       this->extend(request, params)));
                 } else {
                   ::setValue(request, std::string("order_id"), id);
                   if (isTrue(isEqual(isTrigger, true))) {
                     response = awaitValue(this->privatePostCancelTriggerOrder(
                         this->extend(request, params)));
                   } else {
                     response = awaitValue(this->privatePostCancel(
                         this->extend(request, params)));
                   }
                 }
                 //
                 // {
                 //     "result": {
                 //         "subaccount_id": 130837,
                 //         "order_id": "de4f30b6-0dcb-4df6-9222-c1a27f1ad80d",
                 //         "instrument_name": "BTC-PERP",
                 //         "direction": "buy",
                 //         "label": "test1234",
                 //         "quote_id": null,
                 //         "creation_timestamp": 1737540100989,
                 //         "last_update_timestamp": 1737540574696,
                 //         "limit_price": "10000",
                 //         "amount": "0.01",
                 //         "filled_amount": "0",
                 //         "average_price": "0",
                 //         "order_fee": "0",
                 //         "order_type": "limit",
                 //         "time_in_force": "post_only",
                 //         "order_status": "cancelled",
                 //         "max_fee": "211",
                 //         "signature_expiry_sec": 1737540700726,
                 //         "nonce": 1737540100726,
                 //         "signer":
                 //         "0x30CB7B06AdD6749BbE146A6827502B8f2a79269A",
                 //         "signature":
                 //         "0x9cd1a6e32a0699929e4e090c08c548366b1353701ec56e02d5cdf37fc89bd19b7b29e00e57e8383bb6336d73019027a7e2a4364f40859e7a949115024c7f199a1b",
                 //         "cancel_reason": "user_request",
                 //         "mmp": false,
                 //         "is_transfer": false,
                 //         "replaced_order_id":
                 //         "4ccc89ba-3c3d-4047-8900-0aa5fb4ef706",
                 //         "trigger_type": null,
                 //         "trigger_price_type": null,
                 //         "trigger_price": null,
                 //         "trigger_reject_message": null
                 //     },
                 //     "id": "cef61e2a-cb13-4779-8e6b-535361981fad"
                 // }
                 //
                 // {
                 //     "result": {
                 //         "cancelled_orders": 1
                 //     },
                 //     "id": "674e075e-1e8a-4a47-99ff-75efbdd2370f"
                 // }
                 //
                 ccxt::any extendParams = ccxt::dict{
                     {std::string("symbol"), symbol},
                 };
                 ccxt::any order = this->safeDict(
                     response, std::string("result"), ccxt::dict{});
                 if (isTrue(isByClientOrder)) {
                   ::setValue(extendParams, std::string("client_order_id"),
                              clientOrderIdExchangeSpecific);
                 }
                 return this->extend(this->parseOrder(order, market),
                                     extendParams);
               })
        .share();
  }

  /**
   * @method
   * @name derive#cancelAllOrders
   * @see https://docs.derive.xyz/reference/post_private-cancel-by-instrument
   * @see https://docs.derive.xyz/reference/post_private-cancel-all
   * @description cancel all open orders in a market
   * @param {string} [symbol] unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.subaccount_id] *required* the subaccount id
   * @returns {object} an list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  cancelAllOrders(ccxt::any symbol = ccxt::any{},
                  ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any market = ccxt::any{};
                        if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                          market = this->market(symbol);
                        }
                        ccxt::any subaccountId = ccxt::any{};
                        ccxt::any subaccountIdparamsVariable =
                            this->handleDeriveSubaccountId(
                                std::string("cancelAllOrders"), params);
                        subaccountId =
                            ::getValue(subaccountIdparamsVariable, 0);
                        params = ::getValue(subaccountIdparamsVariable, 1);
                        ccxt::any request = ccxt::dict{
                            {std::string("subaccount_id"), subaccountId},
                        };
                        ccxt::any response = ccxt::any{};
                        if (isTrue(!isEqual(market, ccxt::any{}))) {
                          ::setValue(request, std::string("instrument_name"),
                                     ::getValue(market, std::string("id")));
                          response =
                              awaitValue(this->privatePostCancelByInstrument(
                                  this->extend(request, params)));
                        } else {
                          response = awaitValue(this->privatePostCancelAll(
                              this->extend(request, params)));
                        }
                        //
                        // {
                        //     "result": {
                        //         "cancelled_orders": 0
                        //     },
                        //     "id": "9d633799-2098-4559-b547-605bb6f4d8f5"
                        // }
                        //
                        // {
                        //     "id": "45548646-c74f-4ca2-9de4-551e6de49afa",
                        //     "result": "ok"
                        // }
                        //
                        return ccxt::list{this->safeOrder(ccxt::dict{
                            {std::string("info"), response},
                        })};
                      })
        .share();
  }

  /**
   * @method
   * @name derive#fetchOrders
   * @description fetches information on multiple orders made by the user
   * @see https://docs.derive.xyz/reference/post_private-get-orders
   * @param {string} symbol unified market symbol of the market orders were made
   * in
   * @param {int} [since] the earliest time in ms to fetch orders for
   * @param {int} [limit] the maximum number of order structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.paginate] set to true if you want to fetch orders
   * with pagination
   * @param {boolean} [params.trigger] whether the order is a trigger/algo order
   * @param {string} [params.subaccount_id] *required* the subaccount id
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrders(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
              ccxt::any limit = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any paginate = false;
                 ccxt::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchOrders"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallIncremental(
                       std::string("fetchOrders"), symbol, since, limit, params,
                       std::string("page"), 500));
                 }
                 ccxt::any isTrigger =
                     this->safeBool2(params, std::string("trigger"),
                                     std::string("stop"), false);
                 params = this->omit(params, ccxt::list{std::string("trigger"),
                                                        std::string("stop")});
                 ccxt::any subaccountId = ccxt::any{};
                 ccxt::any subaccountIdparamsVariable =
                     this->handleDeriveSubaccountId(std::string("fetchOrders"),
                                                    params);
                 subaccountId = ::getValue(subaccountIdparamsVariable, 0);
                 params = ::getValue(subaccountIdparamsVariable, 1);
                 ccxt::any request = ccxt::dict{
                     {std::string("subaccount_id"), subaccountId},
                 };
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("instrument_name"),
                              ::getValue(market, std::string("id")));
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("page_size"), limit);
                 } else {
                   ::setValue(request, std::string("page_size"), 500);
                 }
                 if (isTrue(isEqual(isTrigger, true))) {
                   ::setValue(request, std::string("status"),
                              std::string("untriggered"));
                 }
                 ccxt::any response = awaitValue(
                     this->privatePostGetOrders(this->extend(request, params)));
                 //
                 // {
                 //     "result": {
                 //         "subaccount_id": 130837,
                 //         "orders": [
                 //             {
                 //                 "subaccount_id": 130837,
                 //                 "order_id":
                 //                 "63a80cb8-387b-472b-a838-71cd9513c365",
                 //                 "instrument_name": "BTC-PERP",
                 //                 "direction": "buy",
                 //                 "label": "test1234",
                 //                 "quote_id": null,
                 //                 "creation_timestamp": 1737551053207,
                 //                 "last_update_timestamp": 1737551053207,
                 //                 "limit_price": "10000",
                 //                 "amount": "0.01",
                 //                 "filled_amount": "0",
                 //                 "average_price": "0",
                 //                 "order_fee": "0",
                 //                 "order_type": "limit",
                 //                 "time_in_force": "post_only",
                 //                 "order_status": "open",
                 //                 "max_fee": "211",
                 //                 "signature_expiry_sec": 1737551652765,
                 //                 "nonce": 1737551052765,
                 //                 "signer":
                 //                 "0x30CB7B06AdD6749BbE146A6827502B8f2a79269A",
                 //                 "signature":
                 //                 "0x35535ccb1bcad509ecc435c79e966174db6403fc9aeee1e237d08a941014c57b59279dfe4be39e081f9921a53eaad59cb2a151d9f52f2d05fc47e6280254952e1c",
                 //                 "cancel_reason": "",
                 //                 "mmp": false,
                 //                 "is_transfer": false,
                 //                 "replaced_order_id": null,
                 //                 "trigger_type": null,
                 //                 "trigger_price_type": null,
                 //                 "trigger_price": null,
                 //                 "trigger_reject_message": null
                 //             }
                 //         ],
                 //         "pagination": {
                 //             "num_pages": 1,
                 //             "count": 1
                 //         }
                 //     },
                 //     "id": "e5a88d4f-7ac7-40cd-aec9-e0e8152b8b92"
                 // }
                 //
                 ccxt::any data =
                     this->safeValue(response, std::string("result"));
                 ccxt::any page =
                     this->safeInteger(params, std::string("page"));
                 if (isTrue(!isEqual(page, ccxt::any{}))) {
                   ccxt::any pagination =
                       this->safeDict(data, std::string("pagination"));
                   ccxt::any currentPage = this->safeInteger(
                       pagination, std::string("num_pages"), 0);
                   if (isTrue(isGreaterThan(page, currentPage))) {
                     return ccxt::list{};
                   }
                 }
                 ccxt::any orders =
                     this->safeList(data, std::string("orders"), ccxt::list{});
                 return this->parseOrders(orders, market, since, limit);
               })
        .share();
  }

